class Solution {
public:
    vector<int> maxSubgraphScore(int n, vector<vector<int>>& edges, vector<int>& good) {
        vector<vector<int>> adj(n);
        for (auto &e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<int> parent(n, -1), order(1, 0), down(n), ans(n);
        for (int i = 0; i < (int)order.size(); ++i) {
            int u = order[i];
            for (int v : adj[u]) if (v != parent[u]) {
                parent[v] = u;
                order.push_back(v);
            }
        }
        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            down[u] = good[u] ? 1 : -1;
            for (int v : adj[u]) if (parent[v] == u)
                down[u] += max(0, down[v]);
        }
        ans[0] = down[0];
        for (int u : order) {
            for (int v : adj[u]) if (parent[v] == u)
                ans[v] = down[v] + max(0, ans[u] - max(0, down[v]));
        }
        return ans;
    }
};
